    },
    {
      "activity_id": "A5",
      "activity_name": "TwitterStream Source Module Porting",
      "activity_description": "Port the twitterstream module from Spring XD to Spring Cloud Stream as a source module.",
      "activity_description": "Port the twitterstream module from Spring XD to Spring Cloud Stream as a source module.",
